export default class CheckoutStarted {
    constructor(details) {
        this.transaction = details;
    }

    toSegment() {
        return {
            event: 'Checkout Started',
            properties: {
                checkout_id: window.initialData?.cart?.id,
                order_id: this.transaction?.order_id?.toString() || '',
                cart_id: this.transaction?.cart_id?.toString() || '',
                affiliation: this.transaction?.affiliation || '',
                value: this.transaction?.value || 0,
                revenue: this.transaction?.revenue || 0,
                shipping: this.transaction?.shipping || 0,
                tax: this.transaction?.tax || 0,
                discount: this.transaction?.discount || 0,
                coupon: this.transaction?.coupon || '',
                currency: this.transaction?.currency || '',
                products: (this.transaction?.products || []).map(product => ({
                    product_id: product?.product_id?.toString() || '',
                    sku: product?.sku || '',
                    name: product?.name || '',
                    price: product?.price || 0,
                    quantity: product?.quantity || 0,
                    category: product?.category || '',
                    url: product?.url || '',
                    image_url: product?.image_url || ''
                }))
            }
        };
    }
}
